// Solve solves an alphametics puzzle of the form "A + BB == ILL".
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, " == ")
	if len(eq) != 2 {
		return nil, errors.New("malformed puzzle")
	}
	addends := strings.Split(eq[0], " + ")
	result := eq[1]
	words := append(addends, result)

	// Collect distinct letters and leading letters.
	letterSet := map[rune]bool{}
	leading := map[rune]bool{}
	for _, w := range words {
		if len(w) > 1 {
			leading[w[0]] = true
		}
		for _, r := range w {
			letterSet[r] = true
		}
	}
	if len(letterSet) > 10 {
		return nil, errors.New("puzzle has more than 10 distinct letters")
	}

	maxLen := 0
	for _, w := range words {
		if len(w) > maxLen {
			maxLen = len(w)
		}
	}

	// rightmost column (0-based from the right) in which each letter appears
	firstCol := map[rune]int{}
	for _, w := range words {
		for i, r := range w {
			col := len(w) - 1 - i
			if c, ok := firstCol[r]; !ok || col < c {
				firstCol[r] = col
			}
