	}
	letters := make([]rune, 0, len(letterSet))
	for r := range letterSet {
		letters = append(letters, r)
	}
	sort.Slice(letters, func(i, j int) bool {
		if firstCol[letters[i]] != firstCol[letters[j]] {
			return firstCol[letters[i]] < firstCol[letters[j]]
